SELECT EXISTS (
    SELECT 1 FROM TB_EMP WHERE EMP_ID = #{userId}
)

SELECT EXISTS (
    SELECT 1
    FROM TB_EMP
    WHERE HOSP_DIV_ID = #{hospitalId}
      AND EMP_ID = #{userId}
      AND ROLE_CD = 'USER'
)

SELECT EXISTS (
    SELECT 1
    FROM TB_WARD
    WHERE HOSP_DIV_ID = #{hospitalId}
      AND WARD_ID = #{wardId}
)

mapper.update:
UPDATE TB_EMP
SET AUTH_ST = 'DISABLED', UPD_DT = CURRENT_TIMESTAMP
WHERE HOSP_DIV_ID = #{hospitalId}
  AND EMP_ID = #{userId}
  AND ROLE_CD = 'USER'
  AND AUTH_ST = 'ACTIVE'

UPDATE TB_EMP
SET AUTH_ST = 'ACTIVE', UPD_DT = CURRENT_TIMESTAMP
WHERE HOSP_DIV_ID = #{hospitalId}
  AND EMP_ID = #{userId}
  AND ROLE_CD = 'USER'
  AND AUTH_ST = 'DISABLED'
